import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls';
import { RenderedNeuron, Segment3D, SynapsePoint } from './types';

interface Props {
    neurons: RenderedNeuron[];
    synapses: SynapsePoint[];
    backgroundSegments: Segment3D[];
    cameraKey: number;
    isDark: boolean;
}

// Fixed MICrONS column bounds (µm, aligned space)
const COL_X_MIN = 250;
const COL_X_MAX = 1500;
const COL_Y_DEPTH = 750; // pia=0, bottom=750; Three.js Y is negated

// Cortical layer boundaries (µm depth from pia)
const LAYER_DEPTHS: Record<string, number> = {
    'L2/3': 250,
    L4: 350,
    L5: 510,
    L6: 740,
};
const LAYER_COLOR = 0x999999;

// Circular synapse sprite — created once
const circleTexture = (() => {
    const size = 64;
    const canvas = document.createElement('canvas');
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d')!;
    ctx.fillStyle = 'white';
    ctx.beginPath();
    ctx.arc(size / 2, size / 2, size / 2 - 1, 0, Math.PI * 2);
    ctx.fill();
    return new THREE.CanvasTexture(canvas);
})();

// Build a canvas-based text sprite (label floating in 3D space)
function makeLabel(text: string, fontSize = 36, color = '#555555'): THREE.Sprite {
    const DPR = 3; // supersampling for sharp text
    const W = 256 * DPR;
    const H = 72 * DPR;
    const canvas = document.createElement('canvas');
    canvas.width = W;
    canvas.height = H;
    const ctx = canvas.getContext('2d')!;
    ctx.scale(DPR, DPR);
    ctx.font = `bold ${fontSize}px Arial`;
    ctx.fillStyle = color;
    ctx.textAlign = 'left';
    ctx.textBaseline = 'middle';
    ctx.fillText(text, 8, H / DPR / 2);
    const tex = new THREE.CanvasTexture(canvas);
    tex.anisotropy = 4;
    return new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: false }));
}

// Build a thin line from (x1,y1,z1) to (x2,y2,z2)
function makeLine(
    x1: number,
    y1: number,
    z1: number,
    x2: number,
    y2: number,
    z2: number,
    color: number,
    opacity = 0.45,
): THREE.Line {
    const geo = new THREE.BufferGeometry().setFromPoints([
        new THREE.Vector3(x1, y1, z1),
        new THREE.Vector3(x2, y2, z2),
    ]);
    const mat = new THREE.LineBasicMaterial({ color, opacity, transparent: true });
    return new THREE.Line(geo, mat);
}

// Dispose and remove all dynamic scene objects
function clearDynamic(scene: THREE.Scene) {
    const toRemove = scene.children.filter((c) => c.userData.dynamic);
    toRemove.forEach((c) => {
        scene.remove(c);
        if ((c as any).geometry) (c as any).geometry.dispose();
        const mat = (c as any).material;
        if (mat) {
            if (Array.isArray(mat)) mat.forEach((m: THREE.Material) => m.dispose());
            else mat.dispose();
        }
    });
}

function tag<T extends THREE.Object3D>(obj: T): T {
    obj.userData.dynamic = true;
    return obj;
}

const ExplorerCanvas3D: React.FC<Props> = ({ neurons, synapses, backgroundSegments, cameraKey, isDark }) => {
    const containerRef = useRef<HTMLDivElement>(null);
    const sceneRef = useRef<THREE.Scene | null>(null);
    const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);
    const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
    const controlsRef = useRef<OrbitControls | null>(null);
    const frameRef = useRef<number>(0);
    const fitRef = useRef<{ center: THREE.Vector3; zBoxMin: number; zBoxMax: number } | null>(null);

    // Initialise Three.js once
    useEffect(() => {
        if (!containerRef.current) return;

        const scene = new THREE.Scene();
        scene.background = new THREE.Color(isDark ? 0x0d1117 : 0xffffff);
        sceneRef.current = scene;

        const camera = new THREE.PerspectiveCamera(
            60,
            containerRef.current.clientWidth / containerRef.current.clientHeight,
            1,
            100000,
        );
        cameraRef.current = camera;

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(containerRef.current.clientWidth, containerRef.current.clientHeight);
        rendererRef.current = renderer;
        containerRef.current.appendChild(renderer.domElement);

        const controls = new OrbitControls(camera, renderer.domElement);
        controls.enableDamping = true;
        controls.dampingFactor = 0.05;
        controlsRef.current = controls;

        scene.add(new THREE.AmbientLight(0xffffff, 1.0));

        const animate = () => {
            frameRef.current = requestAnimationFrame(animate);
            controls.update();
            renderer.render(scene, camera);
        };
        animate();

        const handleResize = () => {
            if (!containerRef.current) return;
            camera.aspect = containerRef.current.clientWidth / containerRef.current.clientHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(containerRef.current.clientWidth, containerRef.current.clientHeight);
        };
        window.addEventListener('resize', handleResize);

        return () => {
            cancelAnimationFrame(frameRef.current);
            window.removeEventListener('resize', handleResize);
            controls.dispose();
            renderer.dispose();
            if (containerRef.current?.contains(renderer.domElement)) {
                containerRef.current.removeChild(renderer.domElement);
            }
        };
    }, []);

    // Update background colour when dark mode toggles
    useEffect(() => {
        if (sceneRef.current) {
            sceneRef.current.background = new THREE.Color(isDark ? 0x0d1117 : 0xffffff);
        }
    }, [isDark]);

    // Rebuild scene whenever neurons / synapses change
    useEffect(() => {
        const scene = sceneRef.current;
        if (!scene) return;

        clearDynamic(scene);
        if (neurons.length === 0 && synapses.length === 0) return;

        const allPositions: THREE.Vector3[] = [];

        // ── Background skeletons (gray, non-interactive, alpha=0.2) ──────────
        if (backgroundSegments.length > 0) {
            const positions = new Float32Array(backgroundSegments.length * 6);
            let i = 0;
            for (const seg of backgroundSegments) {
                positions[i++] = seg.x1;
                positions[i++] = -seg.y1;
                positions[i++] = seg.z1;
                positions[i++] = seg.x2;
                positions[i++] = -seg.y2;
                positions[i++] = seg.z2;
            }
            const geo = new THREE.BufferGeometry();
            geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
            const mat = new THREE.LineBasicMaterial({ color: 0x888888, opacity: 0.2, transparent: true });
            scene.add(tag(new THREE.LineSegments(geo, mat)));
        }

        // ── Neurons ──────────────────────────────────────────────────────────
        for (const neuron of neurons) {
            if (neuron.segments.length === 0) continue;
            const positions = new Float32Array(neuron.segments.length * 6);
            let i = 0;
            for (const seg of neuron.segments) {
                // Y-axis inverted: cortical depth increases downward in SWC,
                // so we negate Y to match ax.invert_yaxis() from viz.py.
                positions[i++] = seg.x1;
                positions[i++] = -seg.y1;
                positions[i++] = seg.z1;
                positions[i++] = seg.x2;
                positions[i++] = -seg.y2;
                positions[i++] = seg.z2;
                allPositions.push(new THREE.Vector3(seg.x2, -seg.y2, seg.z2));
            }
            const geo = new THREE.BufferGeometry();
            geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
            const mat = new THREE.LineBasicMaterial({
                color: new THREE.Color(neuron.color),
                opacity: neuron.opacity,
                transparent: neuron.opacity < 1,
            });
            scene.add(tag(new THREE.LineSegments(geo, mat)));
        }

        // ── Synapses ─────────────────────────────────────────────────────────
        if (synapses.length > 0) {
            const pts = new Float32Array(synapses.length * 3);
            synapses.forEach((s, i) => {
                pts[i * 3] = s.x;
                pts[i * 3 + 1] = -s.y; // Y-inverted
                pts[i * 3 + 2] = s.z;
                allPositions.push(new THREE.Vector3(s.x, -s.y, s.z));
            });
            const geo = new THREE.BufferGeometry();
            geo.setAttribute('position', new THREE.BufferAttribute(pts, 3));
            const mat = new THREE.PointsMaterial({
                color: 0xff0000,
                size: 12,
                map: circleTexture,
                transparent: true,
                alphaTest: 0.5,
                sizeAttenuation: true,
            });
            scene.add(tag(new THREE.Points(geo, mat)));
        }

        if (allPositions.length === 0) return;

        // ── Scene bounds (Z from neuron data; X/Y fixed to column bounds) ────
        const box = new THREE.Box3().setFromPoints(allPositions);
        const zMid = box.getCenter(new THREE.Vector3()).z;
        const zBoxMin = box.min.z;
        const zBoxMax = box.max.z;

        // Store fit params for the camera-reset effect
        fitRef.current = {
            center: new THREE.Vector3((COL_X_MAX + COL_X_MIN) / 2, -COL_Y_DEPTH / 2, zMid),
            zBoxMin,
            zBoxMax,
        };

        // ── EM column wireframe box ───────────────────────────────────────────
        const srcGeo = new THREE.BoxGeometry(COL_X_MAX - COL_X_MIN, COL_Y_DEPTH, zBoxMax - zBoxMin);
        const edgesGeo = new THREE.EdgesGeometry(srcGeo);
        srcGeo.dispose(); // only needed to create edges
        const emBox = new THREE.LineSegments(
            edgesGeo,
            new THREE.LineBasicMaterial({ color: 0xbbbbbb, opacity: 0.3, transparent: true }),
        );
        emBox.position.set((COL_X_MAX + COL_X_MIN) / 2, -COL_Y_DEPTH / 2, zMid);
        scene.add(tag(emBox));

        // ── Cortical layer lines ──────────────────────────────────────────────
        // Spans full column X extent; labels sit at vertical midpoint of each layer.
        const colWidth = COL_X_MAX - COL_X_MIN;
        const spriteW = colWidth * 0.14;
        const spriteH = spriteW * 0.28;

        const layerLabelColor = isDark ? '#aaaaaa' : '#666666';
        const axisXColor = isDark ? '#ff6666' : '#cc3333';
        const axisXHex = isDark ? 0xff6666 : 0xcc3333;
        const axisYColor = isDark ? '#4caf50' : '#2e7d32';
        const axisYHex = isDark ? 0x4caf50 : 0x2e7d32;

        let prevDepth = 0;
        for (const [name, depthMicrons] of Object.entries(LAYER_DEPTHS)) {
            const yThree = -depthMicrons;
            const yMid = -((depthMicrons + prevDepth) / 2);
            scene.add(tag(makeLine(COL_X_MIN, yThree, zMid, COL_X_MAX, yThree, zMid, LAYER_COLOR, 0.4)));

            const label = makeLabel(name, 40, layerLabelColor);
            label.scale.set(spriteW, spriteH, 1);
            label.position.set(COL_X_MIN - spriteW * 0.6, yMid, zMid);
            scene.add(tag(label));

            prevDepth = depthMicrons;
        }

        // ── Floating X / Y axis indicator ────────────────────────────────────
        const axLen = Math.min(colWidth, COL_Y_DEPTH) * 0.15;
        const axOrigin = new THREE.Vector3(COL_X_MIN, box.min.y - axLen * 0.4, zMid);

        const xArrow = new THREE.ArrowHelper(
            new THREE.Vector3(1, 0, 0),
            axOrigin,
            axLen,
            axisXHex,
            axLen * 0.2,
            axLen * 0.12,
        );
        scene.add(tag(xArrow));
        const xLabel = makeLabel('X', 48, axisXColor);
        xLabel.scale.set(spriteW * 0.8, spriteH * 0.8, 1);
        xLabel.position.set(axOrigin.x + axLen * 1.2, axOrigin.y, zMid);
        scene.add(tag(xLabel));

        const yArrow = new THREE.ArrowHelper(
            new THREE.Vector3(0, 1, 0),
            axOrigin,
            axLen,
            axisYHex,
            axLen * 0.2,
            axLen * 0.12,
        );
        scene.add(tag(yArrow));
        const yLabel = makeLabel('Y (pia ↑)', 40, axisYColor);
        yLabel.scale.set(spriteW * 1.1, spriteH * 1.1, 1);
        yLabel.position.set(axOrigin.x, axOrigin.y + axLen * 1.3, zMid);
        scene.add(tag(yLabel));

        // ── Scale bar (100 µm) at bottom-right of EM column ──────────────────
        const scaleColor = isDark ? 0xcccccc : 0x444444;
        const scaleColorStr = isDark ? '#cccccc' : '#444444';
        const sbY = -COL_Y_DEPTH;
        const sbXEnd = COL_X_MAX;
        const sbXStart = sbXEnd - 100; // exactly 100 µm
        const tickH = 15;

        scene.add(tag(makeLine(sbXStart, sbY, zMid, sbXEnd, sbY, zMid, scaleColor, 0.9)));
        scene.add(tag(makeLine(sbXStart, sbY - tickH, zMid, sbXStart, sbY + tickH, zMid, scaleColor, 0.9)));
        scene.add(tag(makeLine(sbXEnd, sbY - tickH, zMid, sbXEnd, sbY + tickH, zMid, scaleColor, 0.9)));

        const scaleLabel = makeLabel('100 µm', 34, scaleColorStr);
        const scaleLabelW = colWidth * 0.1;
        scaleLabel.scale.set(scaleLabelW, scaleLabelW * 0.28, 1);
        scaleLabel.position.set((sbXStart + sbXEnd) / 2, sbY + tickH * 2.5, zMid);
        scene.add(tag(scaleLabel));
    }, [neurons, synapses, backgroundSegments, isDark]);

    // Reset camera only when cameraKey changes — not on every scene rebuild
    useEffect(() => {
        const camera = cameraRef.current;
        const controls = controlsRef.current;
        if (!camera || !controls || !fitRef.current) return;
        const { center, zBoxMin, zBoxMax } = fitRef.current;
        const w = COL_X_MAX - COL_X_MIN;
        const h = COL_Y_DEPTH;
        const d = Math.max(zBoxMax - zBoxMin, 100);
        const maxDim = Math.max(w, h, d);
        // tan formula: dist that fits maxDim within the FOV, scaled to 55% for a tighter default view
        const dist = (maxDim * 0.55) / Math.tan((camera.fov * Math.PI) / 360);
        // No x-offset so the box is horizontally centred; slight y-offset for a top-down angle
        camera.position.set(center.x, center.y + dist * 0.2, center.z + dist);
        controls.target.copy(center);
        controls.update();
    }, [cameraKey]);

    return <div ref={containerRef} style={{ width: '100%', height: '100%' }} />;
};

export default ExplorerCanvas3D;
